```python
def parse_headers(raw: str) -> dict[str, str]:
    headers: dict[str, str] = {}

    for line in raw.splitlines():
        if not line.strip():
            continue

        if ":" not in line:
            raise ValueError("Header line is missing ':'")

        name, value = line.split(":", 1)
        name = name.strip().lower()
        value = value.strip()

        if name in headers:
            headers[name] += ", " + value
        else:
            headers[name] = value

    return headers
```

