def compact(n: int) -> str:
    if n < 1000:
        return str(n)

    def scaled_round(value: int, base: int) -> int:
        return (value * 10 * 2 + base) // (base * 2)

    units = [
        (1_000, "mil"),
        (1_000_000, "mi"),
        (1_000_000_000, "bi"),
    ]

    i = 0
    for j, (base, _) in enumerate(units):
        if n >= base:
            i = j
        else:
            break

    base, unit = units[i]
    value10 = scaled_round(n, base)

    while i + 1 < len(units) and value10 >= 10000:
        i += 1
        base, unit = units[i]
        value10 = scaled_round(n, base)

    whole, frac = divmod(value10, 10)
    return f"{whole}{''.join([',', str(frac)]) if frac else ''} {unit}"
```

