def compare_versions(a: str, b: str) -> int:
    def parse(v: str):
        v = v.split('+', 1)[0]
        if '-' in v:
            core, pre = v.split('-', 1)
            pre_ids = pre.split('.') if pre else []
        else:
            core = v
            pre_ids = []

        core_ids = [int(x) for x in core.split('.')[:3]]
        while len(core_ids) < 3:
            core_ids.append(0)

        return core_ids, pre_ids

    def compare_identifiers(x: str, y: str) -> int:
        x_numeric = x.isdigit()
        y_numeric = y.isdigit()

        if x_numeric and y_numeric:
            xi, yi = int(x), int(y)
            return -1 if xi < yi else (1 if xi > yi else 0)

        if x_numeric != y_numeric:
            return -1 if x_numeric else 1

        if x != y:
            return -1 if x < y else 1

        return 0

    a_core, a_pre = parse(a)
    b_core, b_pre = parse(b)

    for ai, bi in zip(a_core, b_core):
        if ai < bi:
            return -1
        if ai > bi:
            return 1

    if not a_pre and not b_pre:
        return 0
    if not a_pre:
        return 1
    if not b_pre:
        return -1

    for ai, bi in zip(a_pre, b_pre):
        result = compare_identifiers(ai, bi)
        if result != 0:
            return result

    if len(a_pre) < len(b_pre):
        return -1
    if len(a_pre) > len(b_pre):
        return 1
    return 0
```

