def build_order(deps: dict[str, list[str]]) -> list[str]:
    import heapq

    nodes = set(deps)
    for d in deps.values():
        nodes.update(d)

    dependents = {item: [] for item in nodes}
    indegree = {item: 0 for item in nodes}

    for item, item_deps in deps.items():
        for dep in set(item_deps):
            dependents[dep].append(item)
            indegree[item] += 1

    ready = [item for item in nodes if indegree[item] == 0]
    heapq.heapify(ready)

    order = []
    while ready:
        item = heapq.heappop(ready)
        order.append(item)

        for dependent in dependents[item]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(ready, dependent)

    if len(order) != len(nodes):
        raise ValueError("dependency cycle detected")

    return order
```

