def natural_sorted(names: list[str]) -> list[str]:
    def key(name: str):
        parts = []
        i = 0
        n = len(name)

        while i < n:
            if name[i].isdigit():
                j = i
                while j < n and name[j].isdigit():
                    j += 1
                parts.append((0, int(name[i:j])))
                i = j
            else:
                j = i
                while j < n and not name[j].isdigit():
                    j += 1
                parts.append((1, name[i:j].lower()))
                i = j

        return tuple(parts)

    return sorted(names, key=key)
```

