def wrap(text: str, width: int) -> list[str]:
    if width <= 0:
        return []

    lines: list[str] = []
    current: list[str] = []

    for word in text.split():
        if len(word) > width:
            if current:
                lines.append(" ".join(current))
                current = []

            for i in range(0, len(word), width):
                piece = word[i:i + width]
                if current:
                    candidate = f"{' '.join(current)} {piece}" if current else piece
                else:
                    candidate = piece

                if len(candidate) <= width:
                    current.append(piece)
                else:
                    if current:
                        lines.append(" ".join(current))
                    current = [piece]
        else:
            if current:
                candidate = f"{' '.join(current)} {word}"
            else:
                candidate = word

            if len(candidate) <= width:
                current.append(word)
            else:
                if current:
                    lines.append(" ".join(current))
                current = [word]

    if current:
        lines.append(" ".join(current))

    return lines
```

