def deep_merge(base: dict, override: dict) -> dict:
    def deep_copy(value):
        if isinstance(value, dict):
            return {key: deep_copy(item) for key, item in value.items()}
        if isinstance(value, list):
            return [deep_copy(item) for item in value]
        return value

    def merge_into(target: dict, source: dict) -> None:
        for key, source_value in source.items():
            if source_value is None:
                target.pop(key, None)
            elif isinstance(source_value, dict) and isinstance(target.get(key), dict):
                merge_into(target[key], source_value)
            else:
                target[key] = deep_copy(source_value)

    result = deep_copy(base)
    merge_into(result, override)
    return result
