```python
import ipaddress

def ip_allowed(ip: str, networks: list[str]) -> bool:
    try:
        candidates = [ipaddress.ip_address(ip)]
        if candidates[0].version == 6 and candidates[0].ipv4_mapped is not None:
            candidates.append(candidates[0].ipv4_mapped)
    except ValueError:
        return False

    for network in networks:
        net = ipaddress.ip_network(network, strict=False)

        # A network may have host bits set; ip_network(..., strict=False)
        # already normalizes e.g. "10.0.0.1/8" to "10.0.0.0/8".

        for candidate in candidates:
            try:
                if candidate in net:
                    return True
            except TypeError:
                # Different address families; continue checking other candidates/networks.
                pass

        # Also allow IPv4 addresses to match IPv4-mapped IPv6 networks,
        # and IPv4-mapped IPv6 addresses to match IPv4 networks.
        if net.version == 6 and net.network_address.ipv4_mapped is not None:
            net_end = net.broadcast_address
            if net_end.ipv4_mapped is not None:
                # The whole IPv6 network falls within the IPv4-mapped range.
                mapped_net = ipaddress.ip_network(
                    f"{net.network_address.ipv4_mapped}/{32 - (net.prefixlen - 96)}",
                    strict=False,
                )
                for candidate in candidates:
                    try:
                        if candidate in mapped_net:
                            return True
                    except TypeError:
                        pass

    return False
