def is_woodall(n):
    if not isinstance(n, int) or isinstance(n, bool) or n < 1:
        return False

    target = n + 1
    upper = target.bit_length() + 1

    low, high = 1, upper
    while low <= high:
        mid = (low + high) // 2
        value = mid * (1 << mid)
        if value == target:
            return True
        elif value < target:
            low = mid + 1
        else:
            high = mid - 1

    return False
