def compact(n: int) -> str:
    if n < 1000:
        return str(n)

    units = ((1000, "mil"), (1_000_000, "mi"), (1_000_000_000, "bi"))

    for divisor, label in units:
        value = (10 * n + divisor // 2) // divisor
        if value < 10_000:
            break

    if value >= 10_000:
        value = 10_000

    if value % 10 == 0:
        return f"{value // 10} {label}"
    return f"{value // 10},{value % 10} {label}"
