from decimal import Decimal

def parse_brl(s: str) -> Decimal:
    if not isinstance(s, str):
        raise ValueError("invalid Brazilian currency value")

    text = s.strip()
    if not text:
        raise ValueError("invalid Brazilian currency value")

    negative = False

    if text.startswith("("):
        if not text.endswith(")"):
            raise ValueError("invalid Brazilian currency value")
        negative = True
        text = text[1:-1].strip()
        if not text:
            raise ValueError("invalid Brazilian currency value")

    if text.startswith("-"):
        negative = True
        text = text[1:].strip()
        if not text:
            raise ValueError("invalid Brazilian currency value")

    if text.startswith("R$"):
        text = text[2:].lstrip(" ")
    elif text.startswith("R $"):
        raise ValueError("invalid Brazilian currency value")

    if not text:
        raise ValueError("invalid Brazilian currency value")

    if "," in text:
        integer_part, cents_part = text.split(",", 1)
        if len(cents_part) != 2 or not cents_part.isdigit():
            raise ValueError("invalid Brazilian currency value")
    else:
        integer_part = text
        cents_part = "00"

    if not integer_part.isdigit():
        raise ValueError("invalid Brazilian currency value")

    if "." in integer_part:
        groups = integer_part.split(".")
        if not (1 <= len(groups[0]) <= 3):
            raise ValueError("invalid Brazilian currency value")
        if any(len(group) != 3 for group in groups[1:]):
            raise ValueError("invalid Brazilian currency value")
        value = Decimal(integer_part.replace(".", "") + "." + cents_part)
    else:
        value = Decimal(integer_part + "." + cents_part)

    if negative:
        value = -value

    return value.quantize(Decimal("0.01"))
