def add_business_days(d: date, n: int, holidays: set[date]) -> date:
    def is_business_day(day: date) -> bool:
        return day.weekday() < 5 and day not in holidays

    if n == 0:
        if is_business_day(d):
            return d
        cur = d
        while True:
            cur = date.fromordinal(cur.toordinal() + 1)
            if is_business_day(cur):
                return cur

    cur = d
    if n > 0:
        remaining = n
        while remaining:
            cur = date.fromordinal(cur.toordinal() + 1)
            if cur.weekday() >= 5:
                cur = date.fromordinal(cur.toordinal() + (7 - cur.weekday()))
                continue
            if cur in holidays:
                continue
            remaining -= 1
        return cur

    remaining = -n
    while remaining:
        cur = date.fromordinal(cur.toordinal() - 1)
        if cur.weekday() >= 5:
            cur = date.fromordinal(cur.toordinal() - (cur.weekday() - 4))
            continue
        if cur in holidays:
            continue
        remaining -= 1
    return cur
