def compare_versions(a: str, b: str) -> int:
    def parse(version: str):
        version = version.split('+', 1)[0]
        if version[:1] in {"v", "V"}:
            version = version[1:]

        if "-" in version:
            core, prerelease = version.split("-", 1)
        else:
            core, prerelease = version, None

        core_parts = core.split(".")
        core = []
        for i in range(3):
            if i < len(core_parts):
                try:
                    core.append(int(core_parts[i]))
                except ValueError:
                    core.append(0)
            else:
                core.append(0)

        prerelease_ids = None if prerelease is None else prerelease.split(".")
        return core, prerelease_ids

    def is_numeric(identifier: str) -> bool:
        return identifier != "" and all(ch in "0123456789" for ch in identifier)

    def compare_prerelease(pre_a, pre_b) -> int:
        if pre_a is None and pre_b is None:
            return 0
        if pre_a is None:
            return 1
        if pre_b is None:
            return -1

        for a_id, b_id in zip(pre_a, pre_b):
            a_num = is_numeric(a_id)
            b_num = is_numeric(b_id)

            if a_num and b_num:
                a_val, b_val = int(a_id), int(b_id)
                if a_val != b_val:
                    return -1 if a_val < b_val else 1
            elif a_num != b_num:
                return -1 if a_num else 1
            else:
                if a_id != b_id:
                    return -1 if a_id < b_id else 1

        if len(pre_a) != len(pre_b):
            return -1 if len(pre_a) < len(pre_b) else 1
        return 0

    core_a, pre_a = parse(a)
    core_b, pre_b = parse(b)

    for x, y in zip(core_a, core_b):
        if x != y:
            return -1 if x < y else 1

    return compare_prerelease(pre_a, pre_b)
