import re
from functools import cmp_to_key


def natural_sorted(names: list[str]) -> list[str]:
    def _tokens(s: str) -> list[tuple[int, object]]:
        return [
            (0, int(match.group())) if match.group().isdigit()
            else (1, match.group().lower())
            for match in re.finditer(r"\d+|\D+", s)
        ]

    def _cmp(a: str, b: str) -> int:
        ta = _tokens(a)
        tb = _tokens(b)

        for x, y in zip(ta, tb):
            if x[0] == 0 and y[0] == 0:
                if x[1] != y[1]:
                    return -1 if x[1] < y[1] else 1
            elif x[0] == 1 and y[0] == 1:
                if x[1] != y[1]:
                    return -1 if x[1] < y[1] else 1
            else:
                return -1 if x[0] < y[0] else 1

        if len(ta) != len(tb):
            return -1 if len(ta) < len(tb) else 1
        return 0

    return sorted(names, key=cmp_to_key(_cmp))
