def latest_by_key(records: list[dict], key: str) -> list[dict]:
    from datetime import datetime, timezone

    def parse_updated_at(value: str) -> datetime:
        text = value.strip()
        if text.endswith(("Z", "z")):
            text = text[:-1] + "+00:00"
        parsed = datetime.fromisoformat(text)
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=timezone.utc)
        return parsed

    latest: dict = {}
    order: list = []

    for record in records:
        record_key = record[key]
        ts = parse_updated_at(record["updated_at"])

        if record_key not in latest:
            latest[record_key] = (ts, record)
            order.append(record_key)
        else:
            prev_ts, _ = latest[record_key]
            if ts >= prev_ts:
                latest[record_key] = (ts, record)

    return [latest[k][1] for k in order]
