def minPath(grid, k):
    n = len(grid)

    if k == 0:
        return []

    start_r, start_c = 0, 0
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                start_r, start_c = i, j
                break
        else:
            continue
        break

    r, c = start_r, start_c
    path = []

    for _ in range(k):
        path.append(grid[r][c])

        best_r, best_c = None, None
        best_val = None

        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                val = grid[nr][nc]
                if best_val is None or val < best_val:
                    best_val = val
                    best_r, best_c = nr, nc

        r, c = best_r, best_c

    return path
