```python
def find_Rotations(s: str) -> int:
    n = len(s)
    if n == 0:
        return 0

    pi = [0] * n
    for i in range(1, n):
        j = pi[i - 1]
        while j > 0 and s[i] != s[j]:
            j = pi[j - 1]
        if s[i] == s[j]:
            j += 1
        pi[i] = j

    period = n - pi[-1]
    return period if n % period == 0 else n
```

