def is_woodall(number):
    if number <= 0:
        return False

    target = number + 1
    low, high = 1, target.bit_length()

    while low <= high:
        mid = (low + high) // 2
        value = mid << mid  # mid * 2**mid

        if value == target:
            return True
        elif value < target:
            low = mid + 1
        else:
            high = mid - 1

    return False
```

