def parse_headers(raw: str) -> dict[str, str]:
    headers: dict[str, str] = {}

    for line in raw.replace("\r\n", "\n").split("\n"):
        if not line.strip():
            continue

        if ":" not in line:
            raise ValueError("Header line must contain a ':'")

        name, value = line.split(":", 1)
        key = name.strip().lower()
        value = value.strip()

        if key in headers:
            headers[key] += f", {value}"
        else:
            headers[key] = value

    return headers
```

