import re
from datetime import datetime


def parse_log(line: str) -> dict:
    pattern = re.compile(
        r"^\s*(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}(?:[.,]\d{1,6})?)"
        r"\s+\[([A-Za-z]+)\]\s+(.*)$"
    )
    match = pattern.match(line)
    if not match:
        raise ValueError("Invalid log line")

    ts_raw, level_raw, rest = match.groups()

    ts_match = re.match(r"(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})(?:[.,](\d{1,6}))?$", ts_raw)
    if not ts_match:
        raise ValueError("Invalid timestamp")

    base_ts, fraction = ts_match.groups()
    try:
        ts = datetime.strptime(base_ts, "%Y-%m-%d %H:%M:%S")
    except ValueError as exc:
        raise ValueError("Invalid timestamp") from exc

    if fraction:
        ts = ts.replace(microsecond=int(fraction.ljust(6, "0")))

    level = level_raw.upper()
    if level == "WARNING":
        level = "WARN"

    idx = rest.find(": ")
    if idx != -1:
        logger = rest[:idx]
        msg = rest[idx + 2:]
    elif rest.endswith(":"):
        logger = rest[:-1]
        msg = ""
    else:
        raise ValueError("Invalid log line")

    if not logger:
        raise ValueError("Invalid log line")

    return {"ts": ts, "level": level, "logger": logger, "msg": msg}
```

