def compact(n: int) -> str:
    if n < 1000:
        return str(n)

    units = ("mil", "mi", "bi")

    for i, unit in enumerate(units):
        scale = 1000 ** (i + 1)
        q, r = divmod(n * 10, scale)
        if 2 * r >= scale:
            q += 1

        if q < 10000:
            if q % 10 == 0:
                return f"{q // 10} {unit}"
            return f"{q // 10},{q % 10} {unit}"

    # Fallback for values beyond the defined units.
    scale = 10**9
    q, r = divmod(n * 10, scale)
    if 2 * r >= scale:
        q += 1
    if q % 10 == 0:
        return f"{q // 10} bi"
    return f"{q // 10},{q % 10} bi"
```

