def reached(value, threshold) -> bool:
    from decimal import Decimal

    if type(value) not in (int, float, Decimal) or type(threshold) not in (int, float, Decimal):
        raise TypeError("value and threshold must be int, float, or Decimal")

    def as_written_decimal(x):
        if type(x) is float:
            return Decimal(str(x))
        if type(x) is int:
            return Decimal(x)
        return x

    return as_written_decimal(value) >= as_written_decimal(threshold)
