from decimal import Decimal
import re

def parse_brl(s: str) -> Decimal:
    if not isinstance(s, str):
        raise ValueError("input must be a string")

    t = s.strip()
    negative = False

    if t.startswith('-'):
        negative = True
        t = t[1:].strip()
    elif t.startswith('(') and t.endswith(')'):
        negative = True
        t = t[1:-1].strip()
    else:
        t = t.strip()

    m = re.fullmatch(r'(?:(R\$)?\s*)?((?:\d{1,3}(?:\.\d{3})+|\d+))(?:,(\d{2}))?', t)
    if not m:
        raise ValueError(f"invalid Brazilian currency format: {s!r}")

    prefix, integer_part, cents = m.groups()

    if prefix and prefix != 'R$':
        raise ValueError(f"invalid currency prefix: {s!r}")

    if '.' in integer_part:
        groups = integer_part.split('.')
        if len(groups) > 1 and not (1 <= len(groups[0]) <= 3):
            raise ValueError(f"invalid integer grouping: {s!r}")
        for g in groups[1:]:
            if len(g) != 3:
                raise ValueError(f"invalid integer grouping: {s!r}")
        int_str = integer_part.replace('.', '')
    else:
        int_str = integer_part

    if not int_str.isdigit():
        raise ValueError(f"invalid digits: {s!r}")

    value = int(int_str) * 100 + int(cents if cents is not None else '00')
    result = Decimal(value) / Decimal(100)
    if negative:
        result = -result
    return result
```

