def compare_versions(a: str, b: str) -> int:
    def parse(version: str):
        version = version.strip()
        version = version.split("+", 1)[0]

        if "-" in version:
            core, pre_release = version.split("-", 1)
        else:
            core, pre_release = version, None

        core_parts = core.split(".")
        core_numbers = []
        for i in range(3):
            part = core_parts[i] if i < len(core_parts) else "0"
            core_numbers.append(int(part))

        if pre_release is None:
            pre_release_fields = None
        else:
            pre_release_fields = pre_release.split(".")
            if not pre_release_fields:
                pre_release_fields = None

        return tuple(core_numbers), pre_release_fields

    def is_numeric(identifier: str) -> bool:
        return identifier.isascii() and identifier.isdigit()

    core_a, pre_a = parse(a)
    core_b, pre_b = parse(b)

    if core_a < core_b:
        return -1
    if core_a > core_b:
        return 1

    if pre_a is None and pre_b is None:
        return 0
    if pre_a is None:
        return 1
    if pre_b is None:
        return -1

    for ident_a, ident_b in zip(pre_a, pre_b):
        a_numeric = is_numeric(ident_a)
        b_numeric = is_numeric(ident_b)

        if a_numeric and b_numeric:
            if int(ident_a) < int(ident_b):
                return -1
            if int(ident_a) > int(ident_b):
                return 1
        elif a_numeric:
            return -1
        elif b_numeric:
            return 1
        else:
            if ident_a < ident_b:
                return -1
            if ident_a > ident_b:
                return 1

    if len(pre_a) < len(pre_b):
        return -1
    if len(pre_a) > len(pre_b):
        return 1
    return 0
```

