def natural_sorted(names: list[str]) -> list[str]:
    from functools import cmp_to_key

    def _cmp(a: str, b: str) -> int:
        i = j = 0
        while i < len(a) and j < len(b):
            if a[i].isdigit() and b[j].isdigit():
                start_i, start_j = i, j
                while i < len(a) and a[i].isdigit():
                    i += 1
                while j < len(b) and b[j].isdigit():
                    j += 1

                na = a[start_i:i]
                nb = b[start_j:j]

                # Compare numeric values, ignoring leading zeros.
                if int(na) != int(nb):
                    return -1 if int(na) < int(nb) else 1
            else:
                ca = a[i].casefold()
                cb = b[j].casefold()
                if ca != cb:
                    return -1 if ca < cb else 1
                i += 1
                j += 1

        remaining_a = len(a) - i
        remaining_b = len(b) - j
        if remaining_a != remaining_b:
            return -1 if remaining_a < remaining_b else 1
        return 0

    return sorted(names, key=cmp_to_key(_cmp))
```

