def wrap(text: str, width: int) -> list[str]:
    if width <= 0:
        return []

    words = text.split()
    if not words:
        return []

    lines: list[str] = []
    line: list[str] = []
    length = 0

    def add_word(word: str) -> None:
        nonlocal length
        needed = len(word) + (1 if line else 0)
        if line and length + needed > width:
            lines.append(" ".join(line))
            line = [word]
            length = len(word)
        else:
            line.append(word)
            length += needed

    for word in words:
        if len(word) > width:
            for i in range(0, len(word), width):
                add_word(word[i:i + width])
        else:
            add_word(word)

    if line:
        lines.append(" ".join(line))

    return lines
```

```python
def set_ini_value(text: str, section: str, key: str, value: str) -> str:
    lines = text.split("\n")
    target_section = f"[{section}]"
    new_lines = []
    found_section = False
    found_key = False
    current_section = None

    for line in lines:
        content = line[:-1] if line.endswith("\r") else line
        stripped = content.strip()

        if stripped.startswith("[") and stripped.endswith("]"):
            current_section = stripped
            if current_section == target_section:
                found_section = True
            new_lines.append(line)
            continue

        if found_section and current_section == target_section and not found_key:
            if (
                stripped
                and not stripped.startswith(";")
                and not stripped.startswith("#")
                and "=" in content
            ):
                key_part, _, _ = content.partition("=")
                if key_part.strip() == key:
                    new_lines.append(key + " = " + value + ("\r" if line.endswith("\r") else ""))
                    found_key = True
                    continue

        new_lines.append(line)

    if not found_section:
        raise KeyError(section)
    if not found_key:
        raise KeyError(key)

    return "\n".join(new_lines)
```

