```python
def latest_by_key(records: list[dict], key: str) -> list[dict]:
    from datetime import datetime, timezone

    def parse_updated_at(value: str) -> datetime:
        value = value.strip()
        if value.endswith(("Z", "z")):
            value = value[:-1] + "+00:00"
        parsed = datetime.fromisoformat(value)
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=timezone.utc)
        return parsed

    selected: list[dict] = []
    timestamps: list[datetime] = []
    index: dict = {}

    for record in records:
        k = record[key]

        try:
            i = index.get(k)
        except TypeError:
            i = None
            for j, existing_record in enumerate(selected):
                if existing_record[key] == k:
                    i = j
                    break

        if i is None:
            selected.append(record)
            timestamps.append(parse_updated_at(record["updated_at"]))
            try:
                index[k] = len(selected) - 1
            except TypeError:
                pass
        else:
            new_timestamp = parse_updated_at(record["updated_at"])
            if new_timestamp >= timestamps[i]:
                selected[i] = record
                timestamps[i] = new_timestamp

    return selected
```

```python
def ip_allowed(ip: str, networks: list[str]) -> bool:
    import ipaddress

    # Normalize the candidate address(es). Invalid IP returns False.
    try:
        addr = ipaddress.ip_address(ip)
    except ValueError:
        return False

    candidates = [addr]
    if addr.version == 6 and addr.ipv4_mapped is not None:
        candidates.append(ipaddress.IPv4Address(addr.ipv4_mapped))

    # Parse networks. Invalid network raises ValueError.
    parsed_networks = [ipaddress.ip_network(net, strict=False) for net in networks]

    for network in parsed_networks:
        for candidate in candidates:
            if candidate.version == network.version and candidate in network:
                return True

    return False
```

