def is_woodall(n: int) -> bool:
    if not isinstance(n, int) or isinstance(n, bool):
        return False
    if n < 1:
        return False

    m = n + 1

    for k in range(1, m.bit_length() + 1):
        if (k << k) == m:
            return True

    return False
